let aiGenerating=false,explanationGeneration=0,aiWorker=null,pendingExplanation=null,explanationJob=0,approvedSnapshot='';
const aiDraft=document.getElementById('aiDraft'),aiApprove=document.getElementById('approveExplanation'),aiStatus=document.getElementById('aiStatus'),aiButton=document.getElementById('generateExplanation');
function resetExplanation(){explanationGeneration++;aiDraft.value='';aiApprove.checked=false;approvedSnapshot='';aiStatus.textContent='';document.getElementById('approvalStatus').textContent='ללא אישור המורה, ההסבר לא יופיע אצל הילד וההורה.';}
function invalidateExplanation(){aiApprove.checked=false;approvedSnapshot='';document.getElementById('approvalStatus').textContent='הטיוטה השתנתה — נדרש אישור מחדש של המורה.';}
aiDraft.oninput=invalidateExplanation;
document.getElementById('form').elements.details.addEventListener('input',invalidateExplanation);
document.getElementById('form').elements.subject.addEventListener('change',invalidateExplanation);
aiApprove.onchange=()=>{if(aiGenerating||!aiDraft.value.trim()){aiApprove.checked=false;aiStatus.textContent='יש להכין ולבדוק טיוטה לפני אישור.';return}approvedSnapshot=aiApprove.checked?JSON.stringify({text:aiDraft.value.trim(),instructions:document.getElementById('form').elements.details.value,subject:document.getElementById('form').elements.subject.value}):'';document.getElementById('approvalStatus').textContent=aiApprove.checked?'✓ ההסבר אושר ויופיע לאחר שמירת המשימה.':'ההסבר נשאר טיוטה למורה בלבד.';};
function collectExplanation(teacher){const text=aiDraft.value.trim();if(!text)return null;const snapshot=JSON.stringify({text,instructions:form.elements.details.value,subject:form.elements.subject.value});const approved=aiApprove.checked&&snapshot===approvedSnapshot;return{text,status:approved?'approved':'draft',approvedBy:approved?teacher:null,approvedAt:approved?new Date().toISOString():null};}
function renderExplanation(container,explanation,currentRole){if(explanation.status!=='approved'&&currentRole!=='teacher')return;const box=el('div',null,'notice');box.append(el('b',explanation.status==='approved'?'הסבר עזר — אושר על ידי המורה':'טיוטת הסבר — לא פורסמה לילד ולהורה'));const text=userEl('p',explanation.text);text.style.whiteSpace='pre-wrap';box.append(text);if(explanation.approvedBy)box.append(el('div','אושר על ידי '+explanation.approvedBy,'meta'));container.append(box)}
function explanationWorker(){if(!aiWorker){aiWorker=new Worker('./ai-explanation-worker.js',{type:'module'});aiWorker.onmessage=({data})=>{const job=pendingExplanation;if(!job||job.id!==data.id)return;if(job.generation===explanationGeneration){if(data.type==='progress')aiStatus.textContent=data.status==='progress'?`מוריד מודל הסבר: ${Math.round(data.progress)}%`:'טוען מודל AI למכשיר…';if(data.type==='running')aiStatus.textContent='מכין טיוטת הסבר בעברית…';}if(data.type==='result'){pendingExplanation=null;job.resolve(data.text)}if(data.type==='error'){pendingExplanation=null;job.reject(new Error(data.message))}};aiWorker.onerror=()=>{if(pendingExplanation){pendingExplanation.reject(new Error('טעינת מודל ההסבר נכשלה.'));pendingExplanation=null}aiWorker.terminate();aiWorker=null}}return aiWorker}
aiButton.onclick=async()=>{if(aiGenerating)return;const instructions=form.elements.details.value.trim();if(form.elements.kind.value==='none'||!instructions){aiStatus.textContent='הוסיפו תחילה את הוראות שיעורי הבית.';return}if(!navigator.gpu){aiStatus.textContent='יצירה מקומית דורשת דפדפן עם WebGPU. נסו Chrome או Edge מעודכן במחשב, או הדביקו הסבר לבדיקה ואישור.';return}if(aiDraft.value.trim()&&!confirm('להחליף את טיוטת ההסבר הקיימת בטיוטה חדשה?'))return;const generation=explanationGeneration,aiClass=activeClassId(),id=++explanationJob;aiGenerating=true;aiButton.disabled=true;aiApprove.disabled=true;invalidateExplanation();aiStatus.textContent='מתחיל יצירת הסבר מקומי. בהפעלה הראשונה יורד מודל גדול…';try{const text=await new Promise((resolve,reject)=>{pendingExplanation={id,generation,resolve,reject};explanationWorker().postMessage({id,language:languageName(),instructions,subject:form.elements.subject.value,resources:taskResources.map(r=>({title:r.title,note:r.note||''}))})});if(generation!==explanationGeneration)return;aiDraft.value=String(text).slice(0,6000);if(typeof trackUsage==='function')trackUsage('ai_draft_used',aiClass);invalidateExplanation();aiStatus.textContent='הטיוטה מוכנה. בדקו את העברית, הדיוק וההתאמה למשימה לפני אישור.';}catch(e){if(generation===explanationGeneration)aiStatus.textContent='יצירת ההסבר נכשלה: '+e.message+' אפשר לכתוב טיוטה ידנית; שום הסבר לא אושר.';}finally{aiGenerating=false;aiButton.disabled=false;aiApprove.disabled=false}};
